// Low-latency Audio Sound Effects for jekoai Voice
class SoundEffectsService {
  private startAudio: HTMLAudioElement | null = null;
  private stopAudio: HTMLAudioElement | null = null;
  private pasteAudio: HTMLAudioElement | null = null;

  constructor() {
    try {
      this.startAudio = new Audio('data:audio/wav;base64,');
      this.stopAudio = new Audio('data:audio/wav;base64,');
      this.pasteAudio = new Audio('data:audio/wav;base64,');
      
      this.startAudio.volume = 0.55;
      this.stopAudio.volume = 0.5;
      this.pasteAudio.volume = 0.55;
    } catch (e) {
      console.warn('[SoundEffects] Web audio init error:', e);
    }
  }

  public playStart() {
    try {
      if (this.startAudio) {
        this.startAudio.currentTime = 0;
        this.startAudio.play().catch(() => {});
      }
    } catch {}
  }

  public playStop() {
    try {
      if (this.stopAudio) {
        this.stopAudio.currentTime = 0;
        this.stopAudio.play().catch(() => {});
      }
    } catch {}
  }

  public playPaste() {
    try {
      if (this.pasteAudio) {
        this.pasteAudio.currentTime = 0;
        this.pasteAudio.play().catch(() => {});
      }
    } catch {}
  }
}

export const soundEffects = new SoundEffectsService();
